    apple_count = 0
    orange_count = 0
    mango_count = total_fruits

    for fruit in fruit_string.split():
        if fruit.isdigit():
            mango_count -= int(fruit)
        elif fruit == "apple":
            apple_count += 1
        elif fruit == "orange":
            orange_count += 1

    return mango_count - apple_count - orange_count

