                    if wells[i][j] == 1:
                        buckets[j] -= 1
                        wells[i][j] = 0
                        total_water -= 1
                times += 1

    return times

import math

def max_fill(grid, capacity):
    rows, cols = len(grid), len(grid[0])
    wells = [[0] * cols for _ in range(rows)]
    buckets = [0] * cols
    total_water = 0
    times = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                total_water += 1
                wells[i][j] = 1

    for j in range(cols):
        water_in_column = 0
        for i in range(rows):
            if wells[i][j] == 1:
                water_in_column += 1
        times += math.ceil(water_in_column / capacity)

    return times

